package org.jfree.data.statistics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.PublicCloneable;
import org.jfree.data.KeyedObjects2D;
import org.jfree.data.Range;
import org.jfree.data.RangeInfo;
import org.jfree.data.general.AbstractDataset;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class DefaultBoxAndWhiskerCategoryDataset_add_TriageGen2Test {

    private DefaultBoxAndWhiskerCategoryDataset dataset;

    @Before
    public void setUp() {
        dataset = new DefaultBoxAndWhiskerCategoryDataset();
    }

    @Test
    public void testAddFirstItemSetsBounds() {
        // Create item with outliers
        BoxAndWhiskerItem item = new BoxAndWhiskerItem(
                Arrays.asList(10.0, 12.0, 14.0, 16.0, 18.0), // regular values
                10.0, // min outlier
                20.0  // max outlier
        );

        dataset.add(item, "Row1", "Col1");

        assertEquals(10.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(20.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddWithNullOutliersSetsBoundsToNaN() {
        // Create item with no outliers (nulls)
        BoxAndWhiskerItem item = new BoxAndWhiskerItem(
                Arrays.asList(10.0, 12.0, 14.0, 16.0, 18.0),
                null,
                null
        );

        dataset.add(item, "Row1", "Col1");

        // Based on logic: if outliers are null, minval/maxval are NaN.
        // If first item is added and values are NaN, maximumRangeValue becomes NaN.
        // However, the logic for min/max updates uses Double.isNaN check.
        assertEquals(Double.NaN, dataset.getRangeLowerBound(true), 0.0);
        assertEquals(Double.NaN, dataset.getRangeUpperBound(true), 0.0);
    }

    @Test
    public void testAddUpdatesMaxBounds() {
        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(Arrays.asList(1.0), 1.0, 10.0);
        dataset.add(item1, "R1", "C1");

        BoxAndWhiskerItem item2 = new BoxAndWhiskerItem(Arrays.asList(2.0), 2.0, 25.0);
        dataset.add(item2, "R1", "C2");

        // Max should be updated to 25.0
        assertEquals(25.0, dataset.getRangeUpperBound(true), 0.001);
        // Min should remain 1.0
        assertEquals(1.0, dataset.getRangeLowerBound(true), 0.001);
    }

    @Test
    public void testAddUpdatesMinBounds() {
        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(Arrays.asList(10.0), 10.0, 20.0);
        dataset.add(item1, "R1", "C1");

        BoxAndWhiskerItem item2 = new BoxAndWhiskerItem(Arrays.asList(5.0), 5.0, 15.0);
        dataset.add(item2, "R1", "C2");

        // Min should be updated to 5.0
        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001);
        // Max should remain 20.0
        assertEquals(20.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddTriggersUpdateBoundsWhenReplacingMaxOrMinCell() {
        // Add first item
        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(Arrays.asList(10.0), 10.0, 20.0);
        dataset.add(item1, "R1", "C1");

        // Add second item at a different location
        BoxAndWhiskerItem item2 = new BoxAndWhiskerItem(Arrays.asList(5.0), 5.0, 25.0);
        dataset.add(item2, "R2", "C2");

        // Current max is at (R2, C2). 
        // Adding an item at (R2, C2) should trigger updateBounds() because it matches maximumRangeValueRow/Col
        BoxAndWhiskerItem item3 = new BoxAndWhiskerItem(Arrays.asList(30.0), 30.0, 35.0);
        dataset.add(item3, "R2", "C2");

        assertEquals(30.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(35.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddTriggersUpdateBoundsWhenReplacingMinCell() {
        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(Arrays.asList(10.0), 10.0, 20.0);
        dataset.add(item1, "R1", "C1");

        // Max is at (R1, C1). Min is at (R1, C1).
        // Adding item at (R1, C1) triggers updateBounds()
        BoxAndWhiskerItem item2 = new BoxAndWhiskerItem(Arrays.asList(10.0), 10.0, 20.0);
        dataset.add(item2, "R1", "C1");

        // Verify data is still there
        assertNotNull(dataset.getItem(0, 0));
    }

    @Test
    public void testAddWithNoChangeToBounds() {
        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(Arrays.asList(10.0), 10.0, 20.0);
        dataset.add(item1, "R1", "C1");

        // Item that is within current bounds
        BoxAndWhiskerItem item2 = new BoxAndWhiskerItem(Arrays.asList(12.0), 12.0, 18.0);
        dataset.add(item2, "R2", "C2");

        assertEquals(10.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(20.0, dataset.getRangeUpperBound(true), 0.001);
    }
}
